header nav a:hover {
    color: #FFFFFF;
    background-color: rgba(255, 255, 255, .07);
}

header nav a.active {
    color: var(--accent-on-ink);
    background-color: rgba(224, 164, 88, .12);
}

header nav a.btn-nav {
    margin-left: var(--s2);
    background-color: var(--accent);
    color: #FFFFFF;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12);
